  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "A nucleoside analogue is reported to have high oral bioavailability in patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Nipradilol absolute bioavailability was 0.43 ± 0.04 in older subjects, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Praziquantel oral bioavailability was 27.2 ± 5.4% in patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide absolute oral bioavailability was 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Vinorelbine absolute oral bioavailability was 36 ± 10% in patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Maraviroc absolute oral bioavailability was 33% at a 300 mg dose in volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Naldemedine absolute oral bioavailability is estimated at 20–56%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Ketanserin absolute oral bioavailability was about 50% in young healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Mericitabine is reported to have excellent oral bioavailability in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Glasdegib absolute oral bioavailability was 77.12% in healthy volunteers, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental evidence, with high transfer scores, reports oral bioavailability values at or above 20% (mostly 27–77%), and no affirmative low-bioavailability evidence was found; therefore the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query or a close structural analogue.",
    "The query is a large macrocyclic peptide-like scaffold, whereas the evidence molecules are mostly smaller synthetic drugs; permeability, efflux, and first-pass metabolism may differ substantially.",
    "Several supporting values are near the 20% threshold, so borderline classification remains possible."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

